"""The generated SLURM batch script (P1-02 R3)."""

from __future__ import annotations

import json
import subprocess
import sys
from pathlib import Path

import pytest
from hypothesis import HealthCheck, given, settings
from hypothesis import strategies as st

from ebs.core.errors import ExecutorError
from ebs.exec.slurm.jobscript import render_jobscript, runner_arguments
from tests.helpers.executor import PLAN

MAP = PLAN  # any digest will do

GOLDEN = f"""\
#!/bin/bash
# Generated by ebs: runs one action (or one array task) through ebs-runner. Do not edit.
set -euo pipefail
exec /opt/ebs/bin/ebs-runner --plan sha256:{PLAN.hex} --action 'sim[test=smoke,seed=17]' \
--domain cpu-nda --build 42
"""


# R3
def test_template_golden() -> None:
    argv = runner_arguments(
        ["/opt/ebs/bin/ebs-runner"],
        plan=PLAN,
        domain="cpu-nda",
        build=42,
        action="sim[test=smoke,seed=17]",
    )
    assert render_jobscript(argv) == GOLDEN


def test_runner_arguments_array_and_no_build() -> None:
    argv = runner_arguments(["ebs-runner"], plan=PLAN, domain="d", build=None, array_map=MAP)
    assert argv == ["ebs-runner", "--plan", str(PLAN), "--array-map", str(MAP), "--domain", "d"]
    with pytest.raises(ExecutorError, match="exactly one"):
        runner_arguments(["ebs-runner"], plan=PLAN, domain="d", build=None)
    with pytest.raises(ExecutorError, match="exactly one"):
        runner_arguments(
            ["ebs-runner"], plan=PLAN, domain="d", build=None, action="a", array_map=MAP
        )


def test_rejects_unrepresentable_values() -> None:
    with pytest.raises(ExecutorError, match="NUL"):
        render_jobscript(["ebs-runner", "--action", "a\x00b"])
    with pytest.raises(ExecutorError, match="empty"):
        render_jobscript([])


_ECHO = "import json, sys; open(sys.argv[1], 'w').write(json.dumps(sys.argv[2:]))"
_HOSTILE = st.text(
    alphabet=st.characters(blacklist_categories=["Cs"], blacklist_characters="\x00"),
    max_size=40,
)


# R3: whatever an action id contains (quotes, $(…), `…`, newlines, globs, unicode), bash passes
# it to the runner as one unchanged argument and runs nothing else.
@settings(
    max_examples=20, deadline=None, suppress_health_check=[HealthCheck.function_scoped_fixture]
)
@given(values=st.lists(_HOSTILE, min_size=1, max_size=12))
def test_quoting_hostile_values(tmp_path: Path, values: list[str]) -> None:
    out = tmp_path / "argv.json"
    canary = tmp_path / "pwned"
    argv = [sys.executable, "-IS", "-c", _ECHO, str(out), *values, f"$(touch {canary})", "*"]
    script = tmp_path / "job.sh"
    script.write_text(render_jobscript(argv))
    done = subprocess.run(
        ["bash", str(script)], cwd=tmp_path, capture_output=True, text=True, check=False
    )
    assert done.returncode == 0, done.stderr
    assert json.loads(out.read_text()) == [*values, f"$(touch {canary})", "*"]
    assert not canary.exists()
